// @vitest-environment jsdom
// ВРЕМЕННАЯ проверка жизненного цикла (удалить после прогона).
import {createRoot, type Root} from 'react-dom/client';
import {act} from 'react-dom/test-utils';
import {afterEach, beforeEach, describe, expect, it, vi} from 'vitest';
import {buildDemoSeries} from '../demo/demoSeries';

const {created, destroyed} = vi.hoisted(() => ({created: vi.fn(), destroyed: vi.fn()}));

vi.mock('uplot', () => {
  class FakeUPlot {
    root = document.createElement('div');
    over = document.createElement('div');
    constructor(_opts: unknown, data: unknown[], target: HTMLElement) {
      created(data[0]?.length);
      this.root.className = 'uplot';
      this.root.append(this.over);
      target.append(this.root);
    }
    setSize() {}
    setData() {}
    destroy() {
      destroyed();
      this.root.remove();
    }
  }
  return {default: FakeUPlot};
});
vi.mock('uplot/dist/uPlot.min.css', () => ({}));

import {ChartWidget} from './ChartWidget';

const tick = () => new Promise((r) => setTimeout(r, 30));

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;
(globalThis as any).ResizeObserver = class {
  cb: (e: {contentRect: {width: number}}[]) => void;
  constructor(cb: any) {
    this.cb = cb;
  }
  observe() {
    this.cb([{contentRect: {width: 700}}]);
  }
  disconnect() {}
};

let container: HTMLDivElement;
let root: Root;
beforeEach(() => {
  created.mockClear();
  destroyed.mockClear();
  container = document.createElement('div');
  document.body.append(container);
  root = createRoot(container);
});
afterEach(() => {
  act(() => root.unmount());
  container.remove();
});

const radio = (value: string) =>
  [...container.querySelectorAll('input')].find((i) => i.value === value) as HTMLInputElement;

describe('ChartWidget lifecycle', () => {
  it('sales по умолчанию, uplot не грузится до переключения, подсказка и обратное переключение', async () => {
    const series = buildDemoSeries();
    await act(async () => {
      root.render(<ChartWidget title="T" series={series} height={300} />);
    });
    await act(async () => tick());

    expect(container.querySelector('.viz-engine__svg')).not.toBeNull();
    expect(created).not.toHaveBeenCalled();

    const hit = container.querySelector('rect[fill="transparent"]') as SVGRectElement;
    await act(async () => {
      hit.dispatchEvent(new MouseEvent('pointermove', {clientX: 300, bubbles: true}));
    });
    const tip = container.querySelector('.viz-tooltip') as HTMLElement;
    expect(tip.hidden).toBe(false);
    expect(tip.textContent).toContain('Москва');
    expect(tip.textContent).toContain('Онлайн');

    await act(async () => {
      radio('monitoring').click();
    });
    await act(async () => tick());
    expect(created).toHaveBeenCalledTimes(1);
    expect(destroyed).not.toHaveBeenCalled(); // sales-engine снят через replaceChildren, uplot не трогали
    expect(container.querySelector('.viz-engine__svg')).toBeNull();
    expect(container.querySelectorAll('.viz-engine').length).toBe(1);
    expect(container.querySelector('.viz-host')?.getAttribute('aria-busy')).toBeNull();

    await act(async () => {
      radio('sales').click();
    });
    await act(async () => tick());
    expect(container.querySelector('.viz-engine__svg')).not.toBeNull();
    expect(container.querySelectorAll('.viz-engine').length).toBe(1);
    expect(destroyed).toHaveBeenCalledTimes(1);
    expect(created).toHaveBeenCalledTimes(1);
  });

  it('таблица-двойник: 200 последних строк от новых к старым, пропуски как «—»', async () => {
    const series = buildDemoSeries();
    await act(async () => {
      root.render(<ChartWidget title="T" series={series} height={300} />);
    });
    await act(async () => tick());
    await act(async () => {
      [...container.querySelectorAll('button')].find((b) => b.textContent === 'Показать таблицу')!.click();
    });
    const rows = container.querySelectorAll('.viz-table tbody tr');
    expect(rows.length).toBe(200);
    expect(container.querySelector('.viz-table caption')?.textContent).toContain('из 5760');
  });

  it('управляемый режим: виджет не меняет режим сам, а сообщает наверх', async () => {
    const onModeChange = vi.fn();
    const series = buildDemoSeries();
    await act(async () => {
      root.render(<ChartWidget title="T" series={series} mode="sales" onModeChange={onModeChange} />);
    });
    await act(async () => {
      radio('monitoring').click();
    });
    expect(onModeChange).toHaveBeenCalledWith('monitoring');
    // mode не поменяли снаружи: остаётся sales
    await act(async () => tick());
    expect(container.querySelector('.viz-engine__svg')).not.toBeNull();
    expect(created).not.toHaveBeenCalled();
  });
});

